// Kernel: tiled GEMM C = A * B
// A: (M,K) row-major, B: (K,N) row-major, C: (M,N) row-major
template <class TA, class TB, class TC>
__global__ static void __launch_bounds__(512)
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, cute::Stride<int,int> dA,
            TB const* B, cute::Stride<int,int> dB,
            TC      * C, cute::Stride<int,int> dC)
{
  using namespace cute;
  // Larger CTA tile: 128x128 to increase operand reuse and halve B traffic vs 128x64.
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 16; constexpr int LDA = BK + 4;
  constexpr int LDB = BN + 4;
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  int lda = get<0>(dA);
  int ldb = get<1>(dB);
  int ldc = get<0>(dC);
  constexpr int STAGES = 3;
  extern __shared__ char smem_raw[];
  TA* smemA = reinterpret_cast<TA*>(smem_raw);
  TB* smemB = reinterpret_cast<TB*>(smem_raw + STAGES * BM * LDA * sizeof(TA));
  int tid = threadIdx.x;
  int bm = blockIdx.x * BM;
  int bn = blockIdx.y * BN;
  // A tile: 128x16 floats = 512 float4, exactly one per thread.
  int a_row = tid >> 2;
  int a_col = (tid & 3) * 4;
  // B tile: 16x128 floats = 512 float4, exactly one per thread.
  int b_row = tid >> 5;
  int b_col = (tid & 31) * 4;
  const float4* gA0 = reinterpret_cast<const float4*>(A + (bm + a_row) * lda + a_col);
  const float4* gB = reinterpret_cast<const float4*>(B + b_row * ldb + bn + b_col);
  auto load_tile = [&](int kt, int stage) {
    float4* sA0 = reinterpret_cast<float4*>(&smemA[stage * (BM * LDA) + a_row * LDA + a_col]);
    __pipeline_memcpy_async(sA0, gA0 + kt * (BK / 4), 16);
    float4* sB = reinterpret_cast<float4*>(&smemB[stage * (BK * LDB) + b_row * LDB + b_col]);
    __pipeline_memcpy_async(sB, gB + kt * (BK * ldb / 4), 16);
    __pipeline_commit();
  };
  // 16 warps as 4x4. Warp tile 32x32 built from 2x2 WMMA 16x16x8 TF32 fragments.
  int warp = tid >> 5;
  int warp_m = warp >> 2;
  int warp_n = warp & 3;
  int m0 = warp_m * 32;
  int n0 = warp_n * 32;
  wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[2][2];
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    #pragma unroll
    for (int j = 0; j < 2; ++j) wmma::fill_fragment(acc[i][j], 0.0f);
  }
  int k_tiles = K / BK;
  load_tile(0, 0);
  if (k_tiles > 1) load_tile(1, 1);
  for (int kt = 0; kt < k_tiles; ++kt) {
    int stage = kt % STAGES;
    int remaining = k_tiles - 1 - kt;
    if (remaining >= 2) load_tile(kt + 2, (kt + 2) % STAGES);
    __pipeline_wait_prior(remaining >= 2 ? 2 : (remaining == 1 ? 1 : 0));
    __syncthreads();
    const float* sA = &smemA[stage * (BM * LDA)];
    const float* sB = &smemB[stage * (BK * LDB)];
    #pragma unroll
    for (int kk = 0; kk < BK; kk += 8) {
      wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> af[2];
      wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> bf[2];
      #pragma unroll
      for (int i = 0; i < 2; ++i) {
        wmma::load_matrix_sync(af[i], &sA[(m0 + i * 16) * LDA + kk], LDA);
      }
      #pragma unroll
      for (int j = 0; j < 2; ++j) {
        wmma::load_matrix_sync(bf[j], &sB[kk * LDB + n0 + j * 16], LDB);
      }
      #pragma unroll
      for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
          wmma::mma_sync(acc[i][j], af[i], bf[j], acc[i][j]);
        }
      }
    }
    __syncthreads();
  }
  #pragma unroll
  for (int i = 0; i < 2; ++i) {
    #pragma unroll
    for (int j = 0; j < 2; ++j) {
      wmma::store_matrix_sync(C + (bm + m0 + i * 16) * ldc + bn + n0 + j * 16,
                              acc[i][j], ldc, wmma::mem_row_major);
    }
  }
}
// Host wrapper
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda());
  TORCH_CHECK(A.dim()==2 && B.dim()==2);
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat);
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K);
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 16 == 0);
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());
  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();
  auto dA = make_stride(K, 1);
  auto dB = make_stride(1, N);
  auto dC = make_stride(N, 1);
  auto shape_MNK = make_shape(M, N, K);
  dim3 dimBlock(512);
  dim3 dimGrid((M+127)/128, (N+127)/128);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  constexpr int SMEM_BYTES = 56064;
  static bool smem_attr_set = false;
  if (!smem_attr_set) {
    cudaFuncSetAttribute(reinterpret_cast<const void*>(&gemm_device<float, float, float>),
                         cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_BYTES);
    smem_attr_set = true;
  }
  gemm_device<<<dimGrid, dimBlock, SMEM_BYTES, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess);
  return C;
}
